package com.biocircular.compostaje.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestTemplate; import java.math.BigDecimal; import java.util.*;
@Service public class RemoteAuditService { private final RestTemplate http; private final String auditoria,reportes; public RemoteAuditService(RestTemplate h,@Value("${app.auditoria-url}") String a,@Value("${app.reportes-url}") String r){http=h;auditoria=a;reportes=r;} public void audit(String accion,UUID lote){try{http.postForEntity(auditoria+"/api/auditorias/eventos",Map.of("accion",accion,"recurso","LOTE","recursoId",lote.toString()),Void.class);}catch(Exception ignored){}} public void reportFinished(UUID lote,BigDecimal kg){try{http.postForEntity(reportes+"/api/reportes/compostaje/finalizado",Map.of("loteId",lote.toString(),"cantidadKg",kg),Void.class);}catch(Exception ignored){}} }
